package template;

import java.util.Collections;
import java.util.List;

/**
 * Result data carrier generated by LibraryTransaction template method.
 */
public class TransactionResult {
    private final boolean success;
    private final String transactionId;
    private final String transactionType;
    private final String message;
    private final String errorCode;
    private final List<String> executionSteps;
    private final long latencyMs;
    private final Object payload;

    public TransactionResult(boolean success, String transactionId, String transactionType,
                             String message, String errorCode, List<String> executionSteps,
                             long latencyMs, Object payload) {
        this.success = success;
        this.transactionId = transactionId;
        this.transactionType = transactionType;
        this.message = message;
        this.errorCode = errorCode;
        this.executionSteps = executionSteps != null ? executionSteps : Collections.emptyList();
        this.latencyMs = latencyMs;
        this.payload = payload;
    }

    public boolean isSuccess() { return success; }
    public String getTransactionId() { return transactionId; }
    public String getTransactionType() { return transactionType; }
    public String getMessage() { return message; }
    public String getErrorCode() { return errorCode; }
    public List<String> getExecutionSteps() { return executionSteps; }
    public long getLatencyMs() { return latencyMs; }
    public Object getPayload() { return payload; }

    @Override
    public String toString() {
        return String.format("[%s | %s] Success: %b | %s | Steps: %d | Latency: %dms",
                transactionType, transactionId, success, message, executionSteps.size(), latencyMs);
    }
}
